<?php
/** Base HTML dos PDFs de Não Conformidade. Não consulta o banco. */
if (!function_exists('renderNaoConformidadePdfBase')) {
    function renderNaoConformidadePdfBase(array $data, string $tipo, array $specificFields = []): string
    {
        $main = is_array($data['main'] ?? null) ? $data['main'] : [];
        $causes = is_array($data['causes'] ?? null) ? $data['causes'] : [];
        $plans = is_array($data['plans'] ?? null) ? $data['plans'] : [];
        $history = is_array($data['history'] ?? null) ? $data['history'] : [];
        $e = static fn($v): string => htmlspecialchars(trim((string)($v ?? '')) ?: '—', ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $has = static fn($v): bool => trim((string)($v ?? '')) !== '';
        $date = static function ($v): string { $v = trim((string)($v ?? '')); return ($v === '' || $v === '0000-00-00' || $v === '00/00/0000') ? '—' : $v; };
        $plansByCause = [];
        foreach ($plans as $plan) $plansByCause[(string)($plan['CODCAUSA'] ?? '')][] = $plan;
        $field = static function (string $label, $value) use ($e, $has): string {
            if (!$has($value)) return '';
            return '<div class="field"><dt>' . $e($label) . '</dt><dd>' . nl2br($e($value)) . '</dd></div>';
        };
        ob_start(); ?>
<!doctype html><html lang="pt-BR"><head><meta charset="UTF-8">
<title>Não Conformidade - <?= $e($tipo) ?> - <?= $e($main['CODOCORRENCIA'] ?? '') ?></title>
<style>
@page{size:A4;margin:16mm 14mm 15mm}*{box-sizing:border-box}body{margin:0;color:#24332a;background:#fff;font:10px/1.4 Arial,Helvetica,sans-serif}.document{width:100%}.header{display:flex;justify-content:space-between;gap:20px;padding:16px 18px;color:#fff;background:#1f5638;border-radius:7px 7px 0 0}.brand{font-size:17px;font-weight:700;letter-spacing:.2px}.subtitle{margin-top:3px;color:#d9ebdf;font-size:10px}.header-meta{text-align:right;font-size:9px;line-height:1.55}.header-meta strong{display:block;color:#fff;font-size:12px}.intro{padding:10px 18px;background:#edf5ef;border:1px solid #d4e5d8;border-top:0}.intro strong{color:#1f5638;font-size:13px}.section{margin-top:17px;break-inside:avoid}.section-title{margin:0 0 8px;padding:7px 10px;color:#1f5638;background:#e7f1e9;border-left:4px solid #2d7c50;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.25px}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px 14px;margin:0}.field{min-width:0;padding:5px 7px;border-bottom:1px solid #e2e9e3}.field dt{margin-bottom:2px;color:#627269;font-size:8px;font-weight:700;text-transform:uppercase}.field dd{margin:0;color:#26372c;overflow-wrap:anywhere}.note{padding:8px 10px;white-space:pre-wrap;border:1px solid #dce7df;border-radius:4px;background:#fbfdfb;margin-bottom:6px}table{width:100%;border-collapse:collapse;margin-top:5px;page-break-inside:auto}thead{display:table-header-group}tr{page-break-inside:avoid}th{padding:6px 7px;color:#fff;background:#2c6947;font-size:8px;text-align:left;text-transform:uppercase}td{padding:6px 7px;vertical-align:top;border:1px solid #d8e2da;overflow-wrap:anywhere}tbody tr:nth-child(even) td{background:#f6faf7}.plan-title{margin:9px 0 0;padding:5px 7px;color:#356148;background:#eef6f0;border:1px solid #d7e7da;font-size:9px;font-weight:700}.plan-table{margin-top:0;font-size:8.5px}.plan-table th{color:#355442;background:#dcecdf;border:1px solid #c9ddcd}.plan-table td{padding:5px 6px}.empty{padding:9px;color:#69766d;border:1px dashed #cbd8ce;background:#fbfcfb}.status{display:inline-block;padding:2px 6px;border-radius:10px;background:#edf5ef;color:#2d6948;font-size:8px;font-weight:700}.footer{margin-top:20px;padding-top:7px;color:#718077;border-top:1px solid #dbe5dd;font-size:8px;display:flex;justify-content:space-between}@media print{.header,.section-title,th,.plan-title{print-color-adjust:exact;-webkit-print-color-adjust:exact}}
</style></head><body><main class="document">
<header class="header"><div><div class="brand">GREEN PORTAL</div><div class="subtitle">Relatório de consulta de não conformidade</div></div><div class="header-meta"><strong><?= $e(mb_strtoupper($tipo, 'UTF-8')) ?></strong>Ocorrência <?= $e($main['CODOCORRENCIA'] ?? '') ?></div></header>
<div class="intro"><strong>Não Conformidade - <?= $e($tipo) ?></strong><br>Documento gerado para consulta das informações registradas no sistema.</div>
<section class="section"><h2 class="section-title">Identificação</h2><dl class="fields">
<?= $field('Número/Ano',$main['NRANO']??'') ?><?= $field('Código da ocorrência',$main['CODOCORRENCIA']??'') ?><?= $field('Unidade',$main['DSCUNIDADE']??'') ?><?= $field('Etapa',$main['ETAPA']??'') ?><?= $field('Situação',$main['SITUACAO']??'') ?><?= $field('Data da ocorrência',$date($main['DATA_OCORRENCIA']??'')) ?><?= $field('Emitente',$main['NOME_EMISSOR']??'') ?><?= $field('Gestor',$main['NOME_GESTOR']??'') ?><?= $field('Responsável',$main['NOME_RESPONSAVEL']??'') ?><?= $field('Área',$main['DSCAREA']??'') ?><?= $field('Setor',$main['DSCSETOR']??'') ?><?= $field('Lista de distribuição',$main['DSCLISTA']??'') ?>
</dl></section>
<section class="section"><h2 class="section-title">Dados específicos - <?= $e($tipo) ?></h2><dl class="fields"><?php foreach ($specificFields as $label => $key) echo $field($label, $main[$key] ?? ''); ?></dl></section>
<section class="section"><h2 class="section-title">Tipo e classificação</h2><dl class="fields">
<?= $field('Tipo',$main['DSCTIPONAOCONFORMIDADE']??'') ?><?= $field('Código do tipo',$main['CODTIPONAOCONFORMIDADE']??'') ?><?= $field('Classificação',$main['DSCTIPOOCORRENCIA']??'') ?><?= $field('Tipo de ação',$main['DSCTIPOACAO']??'') ?><?= $field('Origem',$main['DSCORIGEMACAO']??'') ?><?= $field('Sistema de gestão',$main['DSCSIGLAGESTAO']??'') ?><?= $field('Possibilidade',$main['POSSIBILIDADE']??'') ?><?= $field('Risco',$main['RISCO']??'') ?>
</dl></section>
<section class="section"><h2 class="section-title">Descrição da ocorrência</h2><?php foreach (['Sumário da ocorrência'=>'SUMARIO_DA_OCORRENCIA','Descrição'=>'DESCRICAO','Providência'=>'PROVIDENCIA','Arquivo/Evidência'=>'ARQUIVO'] as $label=>$key): if($has($main[$key]??'')): ?><div class="note"><strong><?= $e($label) ?></strong><br><?= nl2br($e($main[$key])) ?></div><?php endif; endforeach; ?></section>
<section class="section"><h2 class="section-title">Prazos e avaliações</h2><dl class="fields">
<?= $field('Conclusão prevista',$date($main['DATA_DE_CONCLUSAO_PREVISTA']??'')) ?><?= $field('Prazo de análise',$date($main['PRAZO_ANALISE']??'')) ?><?= $field('Plano encerrado',$main['ENCERRADO']??'') ?><?= $field('Análise da providência',$main['ANALISE_DA_PROVIDENCIA']??'') ?><?= $field('Análise da causa',$main['ANALISE_DA_CAUSA']??'') ?><?= $field('Verificação da eficácia',$main['VERIFICACAO_DA_EFICACIA']??'') ?><?= $field('Recusa do gestor',$main['RECUSA_DO_GESTOR']??'') ?>
</dl></section>
<section class="section"><h2 class="section-title">Causas e planos de ação</h2><?php if(!$causes): ?><div class="empty">Nenhuma causa cadastrada.</div><?php else: ?><table><thead><tr><th>Código</th><th>Tipo</th><th>Descrição da causa</th></tr></thead><tbody><?php foreach($causes as $cause): $code=(string)($cause['CODCAUSA']??''); ?><tr><td><?= $e($code) ?></td><td><?= $e($cause['DSCTIPOCAUSA']??'') ?></td><td><?= nl2br($e($cause['DSCAUSA']??'')) ?></td></tr><tr><td colspan="3" style="padding:0;border:0;background:#fff"><div class="plan-title">Planos de ação da causa <?= $e($code) ?></div><?php $cp=$plansByCause[$code]??[]; if(!$cp): ?><div class="empty">Nenhum plano de ação vinculado a esta causa.</div><?php else: ?><table class="plan-table"><thead><tr><th>Código</th><th>Ação</th><th>Responsável</th><th>Status</th><th>Prioridade</th><th>Período</th><th>Recursos/Observações</th></tr></thead><tbody><?php foreach($cp as $plan): ?><tr><td><?= $e($plan['CODPLANOACAO']??'') ?></td><td><?= nl2br($e($plan['ACAO']??'')) ?></td><td><?= $e($plan['RESPONSAVEL']??'') ?></td><td><span class="status"><?= $e($plan['STATUS']??'') ?></span></td><td><?= $e($plan['PRIORIDADE']??'') ?></td><td><?= $e($date($plan['DATAINICIAL']??'').' a '.$date($plan['DATAFINAL']??'')) ?></td><td><?= nl2br($e(trim((string)($plan['RECURSOS']??'').' '.(string)($plan['obs']??''))?:'—')) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section>
<?php if($history): ?><section class="section"><h2 class="section-title">Histórico dos planos</h2><table><thead><tr><th>Código</th><th>Plano</th><th>Atualização</th><th>Tipo</th><th>Status</th><th>Período</th></tr></thead><tbody><?php foreach($history as $item): ?><tr><td><?= $e($item['CODPLANOACAOHISTORICO']??'') ?></td><td><?= $e($item['CODPLANOACAO']??'') ?></td><td><?= $e($date($item['data_do_update']??'')) ?></td><td><?= $e($item['tipo_de_update']??'') ?></td><td><?= $e($item['STATUS']??'') ?></td><td><?= $e($date($item['DATAINICIAL']??'').' a '.$date($item['DATAFINAL']??'')) ?></td></tr><?php endforeach; ?></tbody></table></section><?php endif; ?>
<footer class="footer"><span>Green Portal | Documento gerado sob demanda</span><span>Não Conformidade <?= $e($main['CODOCORRENCIA']??'') ?></span></footer></main></body></html>
<?php return (string)ob_get_clean();
    }
}
